INSERT INTO `recipe_procedure` VALUES (25547, 1, 'https://i3.meishichina.com/atta/step/2018/06/25/2018062515298816659906591561.jpg', '主材料石斑鱼一条，去鳞去内脏，洗净摆入蒸鱼盘里。');
INSERT INTO `recipe_procedure` VALUES (25547, 2, 'https://i3.meishichina.com/atta/step/2018/06/25/2018062515298816678376591561.jpg', '辅料中的葱、姜片切好。');
INSERT INTO `recipe_procedure` VALUES (25547, 3, 'https://i3.meishichina.com/atta/step/2018/06/25/2018062515298816697596591561.jpg', '将3块姜片放在鱼身上。');
INSERT INTO `recipe_procedure` VALUES (25547, 4, 'https://i3.meishichina.com/atta/step/2018/06/25/2018062515298816707746591561.jpg', '上锅入适量水烧开，放入生食材盖上盖子，用大火隔水蒸十分钟即可离火。');
INSERT INTO `recipe_procedure` VALUES (25547, 5, 'https://i3.meishichina.com/atta/step/2018/06/25/2018062515298825039206591561.jpg', '取出蒸好的鱼，倒掉多余水份和姜片，淋入适合自己口味的蒸鱼豉油。');
INSERT INTO `recipe_procedure` VALUES (25547, 6, 'https://i3.meishichina.com/atta/step/2018/06/25/2018062515298825419846591561.jpg', '放入葱丝。');
INSERT INTO `recipe_procedure` VALUES (25547, 7, 'https://i3.meishichina.com/atta/step/2018/06/25/2018062515298825597036591561.jpg', '起锅加入两大匙油烧热至滚烫冒烟，均匀的淋在鱼表面完成。');
INSERT INTO `recipe_procedure` VALUES (25547, 8, 'https://i3.meishichina.com/atta/step/2018/06/25/2018062515298827077696591561.jpg', '成品。嫩鲜甜。');
INSERT INTO `recipe_procedure` VALUES (27404, 1, 'https://i3.meishichina.com/atta/step/2018/07/10/20180710153120054316110667631.jpg', '所需食材准备就绪。');
INSERT INTO `recipe_procedure` VALUES (27404, 2, 'https://i3.meishichina.com/atta/step/2018/07/10/20180710153120058328610667631.jpg', '彩椒去掉根部。');
INSERT INTO `recipe_procedure` VALUES (27404, 3, 'https://i3.meishichina.com/atta/step/2018/07/10/20180710153120063094210667631.jpg', '用小刀划刻出造型，注意安全。');
INSERT INTO `recipe_procedure` VALUES (27404, 4, 'https://i3.meishichina.com/atta/step/2018/07/10/20180710153120064593910667631.jpg', '依次做好。');
INSERT INTO `recipe_procedure` VALUES (27404, 5, 'https://i3.meishichina.com/atta/step/2018/07/10/20180710153120068679110667631.jpg', '娃娃菜去除叶子改刀成条状。');
INSERT INTO `recipe_procedure` VALUES (27404, 6, 'https://i3.meishichina.com/atta/step/2018/07/10/20180710153120070157210667631.jpg', '小番茄改刀备用。');
INSERT INTO `recipe_procedure` VALUES (27404, 7, 'https://i3.meishichina.com/atta/step/2018/07/10/20180710153120074336010667631.jpg', '水萝卜改刀成条状，依次放入彩椒杯中。');
INSERT INTO `recipe_procedure` VALUES (27404, 8, 'https://i3.meishichina.com/atta/step/2018/07/10/20180710153120079951510667631.jpg', '简单美味，萌翻你哦。');
INSERT INTO `recipe_procedure` VALUES (27404, 9, 'https://i3.meishichina.com/atta/step/2018/07/10/20180710153120081317710667631.jpg', '成品图。');
INSERT INTO `recipe_procedure` VALUES (31456, 1, 'https://i3.meishichina.com/atta/step/2021/08/21/2021082116295163549708086100832.jpg', '黑木耳用冷水泡发。');
INSERT INTO `recipe_procedure` VALUES (31456, 2, 'https://i3.meishichina.com/atta/step/2021/08/21/2021082116295163556319446100832.jpg', '胡萝卜、黄瓜洗干净。');
INSERT INTO `recipe_procedure` VALUES (31456, 3, 'https://i3.meishichina.com/atta/step/2021/08/21/2021082116295163557748046100832.jpg', '洋葱洗干净切成块。');
INSERT INTO `recipe_procedure` VALUES (31456, 4, 'https://i3.meishichina.com/atta/step/2021/08/21/2021082116295163558923856100832.jpg', '胡萝卜、黄瓜切成片。');
INSERT INTO `recipe_procedure` VALUES (31456, 5, 'https://i3.meishichina.com/atta/step/2021/08/21/2021082116295163559956476100832.jpg', '泡发好的木耳入锅焯水后沥干水。');
INSERT INTO `recipe_procedure` VALUES (31456, 6, 'https://i3.meishichina.com/atta/step/2021/08/21/2021082116295163560929706100832.jpg', '起油锅，洋葱入锅炒。');
INSERT INTO `recipe_procedure` VALUES (31456, 7, 'https://i3.meishichina.com/atta/step/2021/08/21/2021082116295163562829276100832.jpg', '洋葱炒出香味，胡萝卜入锅炒。');
INSERT INTO `recipe_procedure` VALUES (31456, 8, 'https://i3.meishichina.com/atta/step/2021/08/21/2021082116295163563855106100832.jpg', '木耳入锅炒。');
INSERT INTO `recipe_procedure` VALUES (31456, 9, 'https://i3.meishichina.com/atta/step/2021/08/21/2021082116295163564809076100832.jpg', '加盐炒。');
INSERT INTO `recipe_procedure` VALUES (31456, 10, 'https://i3.meishichina.com/atta/step/2021/08/21/202108211629516356599826100832.jpg', '食材熟关火，淋入芝麻油。');
INSERT INTO `recipe_procedure` VALUES (31456, 11, 'https://i3.meishichina.com/atta/step/2021/08/21/2021082116295163567093846100832.jpg', '炒均匀即可盛出享用。');
INSERT INTO `recipe_procedure` VALUES (32301, 1, 'https://i3.meishichina.com/atta/step/2021/09/07/202109071630975622657912285245.JPG', '主辅料：咸马哈鱼尾、胡萝卜。');
INSERT INTO `recipe_procedure` VALUES (32301, 2, 'https://i3.meishichina.com/atta/step/2021/09/07/20210907163097562337439285245.JPG', '把咸马哈鱼尾浸泡5小时以上，洗净。');
INSERT INTO `recipe_procedure` VALUES (32301, 3, 'https://i3.meishichina.com/atta/step/2021/09/07/202109071630975623878948285245.JPG', '然后顺长划刀。');
INSERT INTO `recipe_procedure` VALUES (32301, 4, 'https://i3.meishichina.com/atta/step/2021/09/07/202109071630975624384619285245.JPG', '把胡萝卜用擦板擦成丝。');
INSERT INTO `recipe_procedure` VALUES (32301, 5, 'https://i3.meishichina.com/atta/step/2021/09/07/202109071630975624929239285245.JPG', '加入葱姜蒜、橄榄油。');
INSERT INTO `recipe_procedure` VALUES (32301, 6, 'https://i3.meishichina.com/atta/step/2021/09/07/202109071630975625097153285245.JPG', '再加少许盐调味，翻拌均匀。');
INSERT INTO `recipe_procedure` VALUES (32301, 7, 'https://i3.meishichina.com/atta/step/2021/09/07/202109071630975625241604285245.JPG', '另取一盘，先放一些胡萝卜丝铺在盘底。');
INSERT INTO `recipe_procedure` VALUES (32301, 8, 'https://i3.meishichina.com/atta/step/2021/09/07/202109071630975625383246285245.JPG', '上面放马哈鱼尾。');
INSERT INTO `recipe_procedure` VALUES (32301, 9, 'https://i3.meishichina.com/atta/step/2021/09/07/202109071630975625525394285245.JPG', '最上面再放胡萝卜丝。');
INSERT INTO `recipe_procedure` VALUES (32301, 10, 'https://i3.meishichina.com/atta/step/2021/09/07/202109071630975625677710285245.JPG', '锅烧开水，将盘子放入锅中。');
INSERT INTO `recipe_procedure` VALUES (32301, 11, 'https://i3.meishichina.com/atta/step/2021/09/07/20210907163097562582769285245.JPG', '旺火蒸制15分钟即成。');
INSERT INTO `recipe_procedure` VALUES (32301, 12, 'https://i3.meishichina.com/atta/step/2021/09/07/202109071630975625968529285245.JPG', '出锅，即可上桌品味。');
INSERT INTO `recipe_procedure` VALUES (33042, 1, 'https://i3.meishichina.com/atta/step/2021/09/25/20210925163254463230120812729364.jpg', '准备适量菜心。');
INSERT INTO `recipe_procedure` VALUES (33042, 2, 'https://i3.meishichina.com/atta/step/2021/09/25/20210925163254463844035612729364.jpg', '清洗干净备用。');
INSERT INTO `recipe_procedure` VALUES (33042, 3, 'https://i3.meishichina.com/atta/step/2021/09/25/20210925163254464283057712729364.jpg', '准备适量蒜末。');
INSERT INTO `recipe_procedure` VALUES (33042, 4, 'https://i3.meishichina.com/atta/step/2021/09/25/20210925163254464336358712729364.jpg', '锅内烧水，水开下入适量盐。');
INSERT INTO `recipe_procedure` VALUES (33042, 5, 'https://i3.meishichina.com/atta/step/2021/09/25/20210925163254464371996312729364.jpg', '再放入适量油。');
INSERT INTO `recipe_procedure` VALUES (33042, 6, 'https://i3.meishichina.com/atta/step/2021/09/25/20210925163254464419158212729364.jpg', '下入我们准备好的菜心。');
INSERT INTO `recipe_procedure` VALUES (33042, 7, 'https://i3.meishichina.com/atta/step/2021/09/25/20210925163254464473884612729364.jpg', '焯水至断生。');
INSERT INTO `recipe_procedure` VALUES (33042, 8, 'https://i3.meishichina.com/atta/step/2021/09/25/20210925163254464529953212729364.jpg', '捞出装盘。');
INSERT INTO `recipe_procedure` VALUES (33042, 9, 'https://i3.meishichina.com/atta/step/2021/09/25/20210925163254464587066212729364.jpg', '放入适量的蒜末。');
INSERT INTO `recipe_procedure` VALUES (33042, 10, 'https://i3.meishichina.com/atta/step/2021/09/25/20210925163254464647164412729364.jpg', '再加适量的葱丝。');
INSERT INTO `recipe_procedure` VALUES (33042, 11, 'https://i3.meishichina.com/atta/step/2021/09/25/20210925163254464699184512729364.jpg', '热油激出葱蒜的香味。');
INSERT INTO `recipe_procedure` VALUES (33042, 12, 'https://i3.meishichina.com/atta/step/2021/09/25/20210925163254487406958912729364.jpg', '我们的菜心就可以吃咯。');
INSERT INTO `recipe_procedure` VALUES (33042, 13, 'https://i3.meishichina.com/atta/step/2021/09/25/20210925163254464787123712729364.jpg', '成品。');
INSERT INTO `recipe_procedure` VALUES (33077, 1, 'https://i3.meishichina.com/atta/step/2021/09/26/20210926163261067590780410787087.jpg', '把冬瓜去皮去瓤和胡萝卜一样切成块。');
INSERT INTO `recipe_procedure` VALUES (33077, 2, 'https://i3.meishichina.com/atta/step/2021/09/26/20210926163261071930931810787087.jpg', '把冬瓜胡萝卜和已经八分熟的净排骨放入锅中，加水没过食材，加切片的葱姜蒜开大火煮开后改小火慢炖.炖至冬瓜软烂但依然成块即可。快出锅再放盐调味。');
INSERT INTO `recipe_procedure` VALUES (33077, 3, 'https://i3.meishichina.com/atta/step/2021/09/26/20210926163261091804928110787087.jpg', '出锅淋几滴香油盛出即可。味道鲜香。');
INSERT INTO `recipe_procedure` VALUES (35616, 1, 'https://i3.meishichina.com/atta/step/2022/02/07/20220207164421821450988112848515.jpg', '食材大合照。');
INSERT INTO `recipe_procedure` VALUES (35616, 2, 'https://i3.meishichina.com/atta/step/2022/02/07/20220207164421821544388112848515.jpg', '调料汁也来张特写。');
INSERT INTO `recipe_procedure` VALUES (35616, 3, 'https://i3.meishichina.com/atta/step/2022/02/07/20220207164421821619596812848515.jpg', '锅里放入清水烧开后，加入切小段的玉米烧15分钟左右。');
INSERT INTO `recipe_procedure` VALUES (35616, 4, 'https://i3.meishichina.com/atta/step/2022/02/07/20220207164421821700043312848515.jpg', '10分钟后加入胡萝卜段再烧5分钟。');
INSERT INTO `recipe_procedure` VALUES (35616, 5, 'https://i3.meishichina.com/atta/step/2022/02/07/20220207164421821757033912848515.jpg', '另起锅放入清水烧开后，放入双花焯水3分钟左右。');
INSERT INTO `recipe_procedure` VALUES (35616, 6, 'https://i3.meishichina.com/atta/step/2022/02/07/20220207164421821820386012848515.jpg', '香菜和小葱切碎末，加入干红辣椒圈。');
INSERT INTO `recipe_procedure` VALUES (35616, 7, 'https://i3.meishichina.com/atta/step/2022/02/07/20220207164421821878942712848515.jpg', '倒入1勺六月鲜特级原汁酱油。');
INSERT INTO `recipe_procedure` VALUES (35616, 8, 'https://i3.meishichina.com/atta/step/2022/02/07/20220207164421821943492312848515.jpg', '1勺味达美臻品蚝油。');
INSERT INTO `recipe_procedure` VALUES (35616, 9, 'https://i3.meishichina.com/atta/step/2022/02/07/20220207164421822010655212848515.jpg', '1勺禾然有机糙米醋。');
INSERT INTO `recipe_procedure` VALUES (35616, 10, 'https://i3.meishichina.com/atta/step/2022/02/07/20220207164421822059526412848515.jpg', '再加入少许烧开的矿泉水搅搅匀。');
INSERT INTO `recipe_procedure` VALUES (35616, 11, 'https://i3.meishichina.com/atta/step/2022/02/07/20220207164421822130147412848515.jpg', '时蔬调料汁调好了。');
INSERT INTO `recipe_procedure` VALUES (35616, 12, 'https://i3.meishichina.com/atta/step/2022/02/07/20220207164421822187362212848515.jpg', '玉米，胡萝卜以及双花随意放在玻璃盘中，倒入适量的烧开的矿泉水。');
INSERT INTO `recipe_procedure` VALUES (35616, 13, 'https://i3.meishichina.com/atta/step/2022/02/07/20220207164421822253873412848515.jpg', '夹一块时蔬，蘸一蘸调料汁，爽口但绝不寡淡。');
INSERT INTO `recipe_procedure` VALUES (36429, 1, 'https://i3.meishichina.com/atta/step/2022/02/28/20220228164601903117745610454906.jpg', '嫩鸡去除体内内脏，洗干净，放入高压锅，盖锅盖，然后大火烧出气，蒸6分钟即可。');
INSERT INTO `recipe_procedure` VALUES (36429, 2, 'https://i3.meishichina.com/atta/step/2022/02/28/20220228164601902988084110454906.jpg', '取出来，切块即可，简单。');
INSERT INTO `recipe_procedure` VALUES (36429, 3, 'https://i3.meishichina.com/atta/step/2022/02/28/20220228164601978672262710454906.JPG', '成品，家常下饭菜！');
INSERT INTO `recipe_procedure` VALUES (36429, 4, 'https://i3.meishichina.com/atta/step/2022/02/28/20220228164601978848531810454906.JPG', '好吃，美味。');
INSERT INTO `recipe_procedure` VALUES (36429, 5, 'https://i3.meishichina.com/atta/step/2022/02/28/20220228164601978962723510454906.JPG', '成品图来一张！');
